136→// FindSessionsForCommit is the exported version of findSessionsForCommit.
137→// Used by the rewind reset command to find sessions to clean up.
138→func (s *ManualCommitStrategy) FindSessionsForCommit(ctx context.Context, baseCommitSHA string) ([]*SessionState, error) {
139→	return s.findSessionsForCommit(ctx, baseCommitSHA)
140→}
