142→// ClearSessionState is the exported version of clearSessionState.
143→// Used by the rewind reset command to clean up session state files.
144→func (s *ManualCommitStrategy) ClearSessionState(ctx context.Context, sessionID string) error {
145→	return s.clearSessionState(ctx, sessionID)
146→}
