654→
655→	if err := strategy.TransitionAndLog(ctx, turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
656→		logging.Warn(logCtx, "turn-end transition failed",
657→			slog.String("error", err.Error()))
658→	}
659→
660→	// Always dispatch to strategy for turn-end handling. The strategy reads
661→	// work items from state (e.g. TurnCheckpointIDs), not the action list.
662→	strat := GetStrategy(ctx)
663→	if err := strat.HandleTurnEnd(ctx, turnState); err != nil {
664→		logging.Warn(logCtx, "turn-end action dispatch failed",
665→			slog.String("error", err.Error()))
