1410→// hasNewTranscriptWork checks if the agent has done work since the last condensation.
1411→// Uses agent-delegated GetTranscriptPosition() — does NOT do file extraction.
1412→// All call sites that need "has the agent done new work?" should use this.
1413→//
1414→// Returns false if: no transcript path, unknown agent type, agent doesn't implement
1415→// TranscriptAnalyzer, or GetTranscriptPosition fails. This is intentional fail-safe
1416→// behavior: callers treat false as "no new work detected", which conservatively
1417→// skips condensation on errors.
1418→func (s *ManualCommitStrategy) hasNewTranscriptWork(ctx context.Context, state *SessionState) bool {
1419→	logCtx := logging.WithComponent(ctx, "checkpoint")
1420→
1421→	if state.TranscriptPath == "" || state.AgentType == "" {
1422→		return false
1423→	}
1424→
1425→	ag, err := agent.GetByAgentType(state.AgentType)
1426→	if err != nil {
1427→		return false
1428→	}
1429→
1430→	// Ensure transcript file is up-to-date (OpenCode creates/refreshes it via `opencode export`).
1431→	// Only wait for flush when the session is active — for idle/ended sessions the
1432→	// transcript is already fully flushed (the Stop hook completed the flush).
1433→	if state.Phase.IsActive() {
1434→		if preparer, ok := ag.(agent.TranscriptPreparer); ok {
1435→			if prepErr := preparer.PrepareTranscript(ctx, state.TranscriptPath); prepErr != nil {
1436→				logging.Debug(logCtx, "prepare transcript failed",
1437→					slog.String("session_id", state.SessionID),
1438→					slog.String("agent_type", string(state.AgentType)),
1439→					slog.String("transcript_path", state.TranscriptPath),
1440→					slog.Any("error", prepErr),
1441→				)
1442→			}
1443→		}
1444→	}
1445→
1446→	analyzer, ok := ag.(agent.TranscriptAnalyzer)
1447→	if !ok {
1448→		return false
1449→	}
1450→
1451→	currentPos, err := analyzer.GetTranscriptPosition(state.TranscriptPath)
1452→	if err != nil {
1453→		logging.Debug(logCtx, "hasNewTranscriptWork: GetTranscriptPosition failed",
1454→			slog.String("session_id", state.SessionID),
1455→			slog.String("transcript_path", state.TranscriptPath),
1456→			slog.Any("error", err),
1457→		)
1458→		return false
1459→	}
1460→
1461→	if currentPos <= state.CheckpointTranscriptStart {
1462→		logging.Debug(logCtx, "hasNewTranscriptWork: no new content",
1463→			slog.String("session_id", state.SessionID),
1464→			slog.Int("current_pos", currentPos),
1465→			slog.Int("start_offset", state.CheckpointTranscriptStart),
1466→		)
1467→		return false
1468→	}
1469→
1470→	return true
1471→}
