1473→// extractModifiedFilesFromLiveTranscript extracts modified files from the live transcript
1474→// (including subagent transcripts) starting from the given offset, and normalizes them
1475→// to repo-relative paths. Returns the normalized file list.
1476→//
1477→// Callers must ensure the transcript is prepared (e.g., via prepareTranscriptForState
1478→// or hasNewTranscriptWork) before calling this function.
1479→func (s *ManualCommitStrategy) extractModifiedFilesFromLiveTranscript(ctx context.Context, state *SessionState, offset int) []string {
1480→	logCtx := logging.WithComponent(ctx, "checkpoint")
1481→
1482→	if state.TranscriptPath == "" || state.AgentType == "" {
1483→		return nil
1484→	}
1485→
1486→	ag, err := agent.GetByAgentType(state.AgentType)
1487→	if err != nil {
1488→		return nil
1489→	}
1490→
1491→	analyzer, ok := ag.(agent.TranscriptAnalyzer)
1492→	if !ok {
1493→		return nil
1494→	}
1495→
1496→	var modifiedFiles []string
1497→
1498→	// For Claude Code, use ExtractAllModifiedFiles which parses the main transcript
1499→	// AND subagent transcripts in a single pass, avoiding redundant parsing.
1500→	if state.AgentType == agent.AgentTypeClaudeCode {
1501→		subagentsDir := filepath.Join(filepath.Dir(state.TranscriptPath), state.SessionID, "subagents")
1502→		transcriptData, readErr := os.ReadFile(state.TranscriptPath)
1503→		if readErr != nil {
1504→			logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: failed to read transcript",
1505→				slog.String("session_id", state.SessionID),
1506→				slog.String("error", readErr.Error()),
1507→			)
1508→		} else {
1509→			// TODO: fix when we refactor this area.
1510→			// rather than instantiating claude specifically, we should iterate agents.
1511→			c := &claudecode.ClaudeCodeAgent{}
1512→			allFiles, extractErr := c.ExtractAllModifiedFiles(transcriptData, offset, subagentsDir)
1513→			if extractErr != nil {
1514→				logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: extraction failed",
1515→					slog.String("session_id", state.SessionID),
1516→					slog.String("error", extractErr.Error()),
1517→				)
1518→			} else {
1519→				modifiedFiles = allFiles
1520→			}
1521→		}
1522→	} else {
1523→		files, _, err := analyzer.ExtractModifiedFilesFromOffset(state.TranscriptPath, offset)
1524→		if err != nil {
1525→			logging.Debug(logCtx, "extractModifiedFilesFromLiveTranscript: main transcript extraction failed",
1526→				slog.String("transcript_path", state.TranscriptPath),
1527→				slog.Any("error", err),
1528→			)
1529→		} else {
1530→			modifiedFiles = files
1531→		}
1532→	}
1533→
1534→	if len(modifiedFiles) == 0 {
1535→		return nil
1536→	}
1537→
1538→	// Normalize to repo-relative paths.
1539→	// Transcript tool_use entries contain absolute paths (e.g., /Users/alex/project/src/main.go)
1540→	// but getStagedFiles/committedFiles use repo-relative paths (e.g., src/main.go).
1541→	basePath := state.WorktreePath
1542→	if basePath == "" {
1543→		if wp, wpErr := paths.WorktreeRoot(ctx); wpErr == nil {
1544→			basePath = wp
1545→		}
1546→	}
1547→	if basePath != "" {
1548→		normalized := make([]string, 0, len(modifiedFiles))
1549→		for _, f := range modifiedFiles {
1550→			if rel := paths.ToRelativePath(f, basePath); rel != "" {
1551→				normalized = append(normalized, rel)
1552→			} else {
1553→				normalized = append(normalized, f)
1554→			}
1555→		}
1556→		modifiedFiles = normalized
1557→	}
1558→
1559→	return modifiedFiles
1560→}
